CREATE TABLE IF NOT EXISTS campuses (id BIGINT PRIMARY KEY, code VARCHAR(10) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS students (id BIGINT AUTO_INCREMENT PRIMARY KEY, roll_no VARCHAR(40) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, campus_id BIGINT, department VARCHAR(100) NOT NULL, year_of_study SMALLINT NOT NULL, attendance DECIMAL(5,2) DEFAULT 100, cgpa DECIMAL(3,2) DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT uq_students_roll_no UNIQUE (roll_no));
CREATE TABLE IF NOT EXISTS courses (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, department VARCHAR(100) NOT NULL, credits SMALLINT NOT NULL, campus_id BIGINT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enrollments (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT, course_id BIGINT, semester VARCHAR(30), grade VARCHAR(3), score DECIMAL(5,2), UNIQUE KEY unique_enrollment(student_id,course_id,semester));
